WITH lines AS (SELECT id, EXPLODE_OUTER(coupon_codes) AS code FROM carts), filtered AS (SELECT *, SUBSTRING(code, 1, 2) AS code_prefix, COALESCE(code, 'N/A') AS resolved_code FROM lines WHERE code IS NOT NULL), cleaned AS (SELECT *, CASE WHEN code IN ('WELCOME5', 'BUNDLE') THEN 'Core' ELSE 'Other' END AS code_group FROM filtered WHERE code IS NOT NULL AND code = 'SPRING10'), cleaned_carts AS (SELECT id, code, code_prefix, resolved_code, code_group, INITCAP(TRIM(code)) AS code_title, COALESCE(code, 'UNKNOWN') AS resolved_code_2 FROM cleaned WHERE code = 'SPRING10'), cleaned_carts_2 AS (SELECT *, CASE WHEN code IN ('WELCOME5', 'BUNDLE') THEN 'Group A' ELSE 'Other' END AS code_group_2 FROM cleaned_carts WHERE code IS NOT NULL), base AS (SELECT id, code, code_prefix, code_title, resolved_code_2, code_group_2, LOWER(code) AS code_lower, LENGTH(code) AS code_length FROM cleaned_carts_2 WHERE code IS NOT NULL AND code IS DISTINCT FROM 'VIP') SELECT code, COUNT(*) AS event_count, SORT_ARRAY(COLLECT_SET(code)) AS code_list FROM base GROUP BY 1 ORDER BY code DESC NULLS LAST
